	@ParameterizedTest(name = "{0}")
	@MethodSource("cases")
	void optimizedSpecializationsPreserveExactNumericBoundaries(Case test) throws Exception {
		Map<Map<String, Value>, Integer> expected = expected(test);
		assertThat(query(memory, test.query(), null)).as("explicit MemoryStore bag for " + test.name)
				.isEqualTo(expected);
		set(NATIVE, "false");
		assertThat(query(repository, test.query(), null)).as("generic LMDB bag for " + test.name).isEqualTo(expected);
		set(NATIVE, "true");
		List<Opened> opened = new ArrayList<>();
		observe(test, opened);
		Map<Map<String, Value>, Integer> optimized;
		try {
			optimized = query(repository, test.query(), test.forcing);
		} finally {
			LmdbNativeDispatchLoop.observeSelections(null);
		}
		assertThat(opened).as("one successfully opened optimized " + test.shape + " route").hasSize(1);
		TupleExpr expression = opened.getFirst().expression;
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
			var triples = new SailDatasetTripleTermSource(repository.getValueFactory(), dataset);
			var priorContext = SlowQueryContextHolder.set(test.query(), Query.QueryType.TUPLE, test.forcing);
			try {
				var strategy = new LmdbNativeEvaluationStrategy(triples, null, null, 0L, new EvaluationStatistics(),
						false);
				QueryEvaluationStep compiled = LmdbNativeAggregateCompiler.tryCompile(expression,
						new QueryEvaluationContext.Minimal((Dataset) null), strategy, source);
				SlotPlan input;
				if (test.shape.aggregate) {
					assertThat(compiled).isInstanceOf(NativeGroupStep.class);
					input = ((NativeGroupStep) compiled).arg;
				} else {
					assertThat(compiled).isInstanceOf(NativeRowsStep.class);
					input = ((NativeRowsStep) compiled).arg;
				}
				List<PatternPlan> patterns = new ArrayList<>();
				int filters = inspect(input, patterns);
				long ranges = patterns.stream().filter(pattern -> pattern.range != null).count();
				if (test.physicalRange) {
					assertThat(ranges).as("real optimized range installation, not merely an equivalent outer FILTER")
							.isPositive();
					assertThat(filters).as("the numeric comparison was absorbed into the physical range").isZero();
				} else {
					assertThat(ranges).as("variable-predicate numeric filtering cannot claim a fixed-predicate range")
							.isZero();
					assertThat(filters).as("the unpushed wildcard comparison remains executable").isPositive();
				}
				List<Opened> reopened = new ArrayList<>();
				observe(test, reopened);
				Map<Map<String, Value>, Integer> actual;
				try (var result = compiled.evaluate(EmptyBindingSet.getInstance())) {
					actual = drain(result);
				} finally {
					LmdbNativeDispatchLoop.observeSelections(null);
				}
				assertThat(reopened).as("the inspected physical plan really executes the requested route").hasSize(1);
				if (test.physicalRange && test.forcing.startsWith("prefixRun,")) {
					assertThat(opened.getFirst().route).isEqualTo(NESTED);
					assertThat(reopened.getFirst().route).isEqualTo(NESTED);
					assertThat(((NativeRowsStep) compiled).prefixRunPlan).isNull();
				}
				System.out.printf("range matrix=%s route=%s reopened=%s ranges=%d filters=%d rows=%d%n",
						test.name, opened.getFirst().route, reopened.getFirst().route, ranges, filters,
						actual.values().stream().mapToInt(Integer::intValue).sum());
				assertThat(optimized).as("normally optimized bag for " + test.name).isEqualTo(expected);
				assertThat(actual).as("inspected physical bag for " + test.name).isEqualTo(expected);
			} finally {
				SlowQueryContextHolder.restore(priorContext);
			}
		}
	}

	private static void observe(Case test, List<Opened> sink) {
		LmdbNativeDecisionPoint point = test.shape.aggregate ? LmdbNativeDecisionPoint.GROUP
				: LmdbNativeDecisionPoint.ROW;
		LmdbNativeDispatchLoop.observeSelections((target, label, id, record) -> {
			if (record.point() == point) {
				assertThat(target).isNotNull();
				assertThat(id).as("the actual opened concrete ID must be an explicitly allowed route")
						.isIn(LmdbNativeForceableStrategies.options(test.forcing));
				assertThat(
						record.entries().stream().filter(entry -> entry.admitted() && entry.id().equals(id)).toList())
								.as("the successful concrete opener agrees with its admitted candidate")
								.hasSize(1);
				sink.add(new Opened(target.clone(), id));
			}
		});
	}

	private record Opened(TupleExpr expression, String route) {
	}

	private static int inspect(SlotPlan plan, List<PatternPlan> patterns) {
		if (plan instanceof PatternPlan pattern) {
			patterns.add(pattern);
			return 0;
		}
		if (plan instanceof MultiJoinPlan join) {
			int count = join.filters.length;
			for (SlotPlan child : join.children) {
				count += inspect(child, patterns);
			}
			return count;
		}
		if (plan instanceof JoinPlan join) {
			return inspect(join.left, patterns) + inspect(join.right, patterns);
		}
		if (plan instanceof FilterPlan filter) {
			return 1 + inspect(filter.arg, patterns);
		}
		if (plan instanceof ExtensionPlan extension) {
			return inspect(extension.arg, patterns);
		}
		throw new AssertionError("unexpected matrix input shape: " + plan.getClass().getSimpleName());
	}

	private static Map<Map<String, Value>, Integer> expected(Case test) {
		List<Map<String, Value>> rows = new ArrayList<>();
		Map<Value, Long> groups = new LinkedHashMap<>();
		LinkedHashSet<Value> distinct = new LinkedHashSet<>();
		long count = 0L;
		long sum = 0L;
		for (int subject = 0; subject < SUBJECTS; subject++) {
			for (int value : new int[] { subject - 4, subject }) {
				if (!test.accepts.test(value)) {
					continue;
				}
				Value s = iri("s" + subject), n = number(value);
				switch (test.shape) {
				case SUBJECT_DISTINCT -> rows.add(Map.of("s", s));
				case OBJECT_DISTINCT, JOIN_DISTINCT_OBJECT -> rows.add(Map.of("n", n));
				case SUBJECT_OBJECT -> rows.add(Map.of("s", s, "n", n));
				case PREDICATE_OBJECT -> {
					rows.add(Map.of("p", iri("score"), "n", n));
					rows.add(Map.of("p", iri("mirror"), "n", n));
				}
				case JOIN_REPLAY, JOIN_ENUM -> {
					for (int tag = 0; tag < tagCount(subject); tag++) {
						rows.add(test.shape == Shape.JOIN_REPLAY ? Map.of("s", s)
								: Map.of("s", s, "n", n, "tag", iri("tag" + tag)));
					}
				}
				case DISTINCT_VALUES -> distinct.add(n);
				case DISTINCT_SUBJECTS -> distinct.add(s);
				case GROUP_VALUES -> groups.merge(n, 1L, Long::sum);
				case SUM_JOIN -> {
					count += tagCount(subject);
					sum += (long) value * tagCount(subject);
				}
				}
			}
		}
		if (test.shape == Shape.DISTINCT_VALUES || test.shape == Shape.DISTINCT_SUBJECTS) {
			rows.add(Map.of("c", number(distinct.size())));
		} else if (test.shape == Shape.GROUP_VALUES) {
			groups.forEach((n, c) -> rows.add(Map.of("n", n, "c", number(c))));
		} else if (test.shape == Shape.SUM_JOIN) {
			rows.add(Map.of("c", number(count), "total", number(sum)));
		}
		Map<Map<String, Value>, Integer> result = new LinkedHashMap<>();
		for (Map<String, Value> row : test.shape.distinct ? new LinkedHashSet<>(rows) : rows) {
			result.merge(row, 1, Integer::sum);
		}
		return result;
	}

	private static Map<Map<String, Value>, Integer> query(SailRepository target, String query, String forcing) {
		try (var connection = target.getConnection()) {
			var prepared = (SailTupleQuery) connection.prepareTupleQuery(query);
			prepared.setForcedLmdbExecutionStrategy(forcing);
			prepared.setMaxExecutionTime(10);
			try (var result = prepared.evaluate()) {
				return drain(result);
			}
		}
	}

	private static Map<Map<String, Value>, Integer> drain(CloseableIteration<? extends BindingSet> result) {
		Map<Map<String, Value>, Integer> bag = new LinkedHashMap<>();
		while (result.hasNext()) {
			BindingSet bindings = result.next();
			Map<String, Value> row = new LinkedHashMap<>();
			for (String name : bindings.getBindingNames()) {
				row.put(name, bindings.getValue(name));
			}
			bag.merge(Map.copyOf(row), 1, Integer::sum);
		}
		return bag;
	}

	private static int tagCount(int subject) {
		return subject % 2 == 0 ? 2 : 1;
	}

	private static IRI iri(String local) {
		return SimpleValueFactory.getInstance().createIRI(NS + local);
	}

	private static Value number(long value) {
		return SimpleValueFactory.getInstance().createLiteral(BigInteger.valueOf(value));
	}

	private void set(String key, String value) {
		if (!previous.containsKey(key)) {
			previous.put(key, System.getProperty(key));
		}
		System.setProperty(key, value);
	}
